#include <bits/stdc++.h>using namespace std;#define int long longint T,n; void O_o(){    cin >> n;    vector<int> a(n + 1);    vector<double> b(n + 1);    for(int i=1;i<=n;i++){        int xx;double yy;cin >> xx >> yy;        a[i] = xx;        b[i] = yy / 100.0;    }    vector<double> dp(n + 2,0.0);    for(int i=n;i>=1;i--){        dp[i] = max(dp[i + 1],dp[i + 1] * (1.0 - b[i]) + a[i]);    }    cout << fixed << setprecision(10) << dp[1] << '\n';} signed main(){    ios::sync_with_stdio(false);    cin.tie(nullptr);cout.tie(nullptr);    cin >> T;    while(T--)O_o();    return 0;}